// Single-thread pthread stubs for bare-metal newlib (Andes riscv64-elf).
// The bare-metal target has no OS scheduler, so real threads are impossible.
// ggml's CPU backend links pthread symbols unconditionally; with n_threads=1
// it never creates a worker thread and every lock is uncontended, so these
// stubs are correct no-ops. Compile with -D_POSIX_THREADS=200809L so newlib's
// pthread.h exposes the declarations.

#include <errno.h>
#include <pthread.h>
#include <sched.h>
#include <stdio.h>
#include <stdlib.h>

int pthread_create(pthread_t *thread, const pthread_attr_t *attr,
                   void *(*start)(void *), void *arg) {
    (void) thread; (void) attr; (void) start; (void) arg;
    fprintf(stderr, "pthread_create: bare-metal build is single-threaded; use n_threads=1\n");
    return EAGAIN;
}

int pthread_join(pthread_t thread, void **retval) {
    (void) thread; (void) retval;
    return 0;
}

int pthread_detach(pthread_t thread) {
    (void) thread;
    return 0;
}

pthread_t pthread_self(void) {
    return (pthread_t) 1;
}

int pthread_mutex_init(pthread_mutex_t *m, const pthread_mutexattr_t *a) {
    (void) m; (void) a;
    return 0;
}

int pthread_mutex_destroy(pthread_mutex_t *m) { (void) m; return 0; }
int pthread_mutex_lock(pthread_mutex_t *m)    { (void) m; return 0; }
int pthread_mutex_trylock(pthread_mutex_t *m) { (void) m; return 0; }
int pthread_mutex_unlock(pthread_mutex_t *m)  { (void) m; return 0; }

int pthread_cond_init(pthread_cond_t *c, const pthread_condattr_t *a) {
    (void) c; (void) a;
    return 0;
}

int pthread_cond_destroy(pthread_cond_t *c)   { (void) c; return 0; }
int pthread_cond_signal(pthread_cond_t *c)    { (void) c; return 0; }
int pthread_cond_broadcast(pthread_cond_t *c) { (void) c; return 0; }

int pthread_cond_wait(pthread_cond_t *c, pthread_mutex_t *m) {
    (void) c; (void) m;
    // No other thread exists to signal this condition: guaranteed deadlock.
    fprintf(stderr, "pthread_cond_wait: deadlock in single-threaded bare-metal build\n");
    abort();
}

int pthread_cond_timedwait(pthread_cond_t *c, pthread_mutex_t *m,
                           const struct timespec *abstime) {
    (void) c; (void) m; (void) abstime;
    return ETIMEDOUT;
}

int sched_yield(void) {
    return 0;
}

