// newlib declares clock_gettime under _POSIX_TIMERS but bare-metal libgloss
// does not implement it. Back it with gettimeofday (semihosted); fall back to
// zero time if the host call is unavailable.
int clock_gettime(clockid_t clock_id, struct timespec *tp) {
    (void) clock_id;
    struct timeval tv;
    if (gettimeofday(&tv, NULL) == 0) {
        tp->tv_sec  = tv.tv_sec;
        tp->tv_nsec = tv.tv_usec * 1000;
    } else {
